INSERT INTO custom_pages_i18n (id, custom_page_id, locale, title, slug, content, summary, meta_title, meta_description) VALUES
  ('cpi-impressum-de', 'cp-impressum', 'de', 'Impressum', 'impressum', '{"html": "<h2>Impressum</h2><h3>Angaben gemäß § 5 TMG / § 18 MStV</h3><p><strong>Verantwortlich für Kartenzahlungen und digitale Verkäufe über diese Website:</strong><br>Orhan Güzel – Softwareentwicklung (Einzelunternehmen)<br>Stralsunder Str. 38<br>41515 Grevenbroich, Deutschland<br>E-Mail: goldmoodastro@gmail.com<br>Umsatzsteuer-Identifikationsnummer gemäß § 27a UStG: DE463832419</p><p>Gemäß § 19 UStG (Kleinunternehmerregelung) wird keine Umsatzsteuer ausgewiesen.</p><h3>Plattformbetreiber (Marke Gold Mood Astro)</h3><p>QUEBAB GIDA FABRİKASI RESTORAN İŞLETMECİLİĞİ EĞLENCE ORGANİZASYON VE KİRALAMA TİCARET LİMİTED ŞİRKETİ<br>Cumhuriyet Mah. D-100 Karayolu Cad. ADM Konaklama Sitesi Outlet Park AVM No:374 İç Kapı No:63 Büyükçekmece / İstanbul, Türkei<br>MERSİS-Nr.: 0632143381600001 · Steuernr.: 6321433816<br>Telefon: +90 212 807 09 59 · E-Mail: goldmoodastro@gmail.com</p><h3>Hinweis zur Art der Leistungen</h3><p>Astrologie-, Tarot- und Numerologie-Beratungen sowie digitale Inhalte dienen ausschließlich der persönlichen Achtsamkeit, Reflexion und Unterhaltung. Es werden keine medizinischen, rechtlichen oder finanziellen Beratungen und keine garantierten Ergebnisse angeboten.</p><h3>Online-Streitbeilegung</h3><p>Plattform der EU-Kommission zur Online-Streitbeilegung: <a href=\\"https://ec.europa.eu/consumers/odr/\\" rel=\\"noopener\\">https://ec.europa.eu/consumers/odr/</a>. Wir sind nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.</p>"}', 'Anbieterkennzeichnung nach § 5 TMG.', 'Impressum — Gold Mood Astro', 'Impressum und Anbieterkennzeichnung von Gold Mood Astro.'),
  ('cpi-impressum-tr', 'cp-impressum', 'tr', 'Impressum (Yasal Bildirim — Almanya)', 'impressum', '{"html": "<h2>Impressum (Almanya Yasal Bildirimi)</h2><h3>§ 5 TMG uyarınca bilgiler</h3><p><strong>Bu web sitesi üzerinden kartla yapılan ödemelerin ve dijital satışların sorumlusu:</strong><br>Orhan Güzel – Softwareentwicklung (şahıs işletmesi)<br>Stralsunder Str. 38<br>41515 Grevenbroich, Almanya<br>E-posta: goldmoodastro@gmail.com<br>KDV Kimlik No (§ 27a UStG): DE463832419</p><p>§ 19 UStG (küçük işletme düzenlemesi) uyarınca KDV gösterilmez.</p><h3>Platform işletmecisi (Gold Mood Astro markası)</h3><p>QUEBAB GIDA FABRİKASI RESTORAN İŞLETMECİLİĞİ EĞLENCE ORGANİZASYON VE KİRALAMA TİCARET LİMİTED ŞİRKETİ<br>Cumhuriyet Mah. D-100 Karayolu Cad. ADM Konaklama Sitesi Outlet Park AVM No:374 İç Kapı No:63 Büyükçekmece / İstanbul<br>MERSİS: 0632143381600001 · Vergi No: 6321433816<br>Telefon: 0212 807 09 59 · E-posta: goldmoodastro@gmail.com</p><h3>Hizmetlerin niteliği</h3><p>Astroloji, tarot ve numeroloji danışmanlıkları ile dijital içerikler yalnızca kişisel farkındalık, kişisel değerlendirme ve eğlence amaçlıdır. Tıbbi, hukuki veya finansal danışmanlık ve garanti edilmiş sonuç sunulmaz.</p>"}', 'Almanya §5 TMG yasal bildirim sayfası.', 'Impressum — Gold Mood Astro', 'Gold Mood Astro Almanya yasal bildirimi (Impressum).'),
  ('cpi-impressum-en', 'cp-impressum', 'en', 'Imprint (Legal Notice — Germany)', 'imprint', '{"html": "<h2>Imprint (Germany)</h2><h3>Information pursuant to § 5 TMG</h3><p><strong>Responsible for card payments and digital sales via this website:</strong><br>Orhan Güzel – Softwareentwicklung (sole proprietorship)<br>Stralsunder Str. 38<br>41515 Grevenbroich, Germany<br>Email: goldmoodastro@gmail.com<br>VAT ID (§ 27a UStG): DE463832419</p><p>No VAT is shown pursuant to § 19 UStG (small business scheme).</p><h3>Platform operator (Gold Mood Astro brand)</h3><p>QUEBAB GIDA FABRİKASI RESTORAN İŞLETMECİLİĞİ EĞLENCE ORGANİZASYON VE KİRALAMA TİCARET LİMİTED ŞİRKETİ<br>Cumhuriyet Mah. D-100 Karayolu Cad. ADM Konaklama Sitesi Outlet Park AVM No:374 İç Kapı No:63 Büyükçekmece / İstanbul, Türkiye<br>MERSİS: 0632143381600001 · Tax No: 6321433816<br>Phone: +90 212 807 09 59 · Email: goldmoodastro@gmail.com</p><h3>Nature of services</h3><p>Astrology, tarot and numerology consulting and digital content serve personal awareness, reflection and entertainment only. No medical, legal or financial advice and no guaranteed outcomes are provided.</p>"}', 'Legal notice pursuant to § 5 TMG.', 'Imprint — Gold Mood Astro', 'Imprint and provider identification of Gold Mood Astro.')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), slug = VALUES(slug), content = VALUES(content),
  summary = VALUES(summary), meta_title = VALUES(meta_title), meta_description = VALUES(meta_description);

INSERT INTO custom_pages_i18n (id, custom_page_id, locale, title, slug, content, summary, meta_title, meta_description) VALUES
  ('cpi-datenschutz-de', 'cp-datenschutz', 'de', 'Datenschutzerklärung', 'datenschutzerklaerung', '{"html": "<h2>Datenschutzerklärung</h2><h3>1. Verantwortlicher</h3><p>Verantwortlicher für die Verarbeitung personenbezogener Daten im Zusammenhang mit Kartenzahlungen und digitalen Verkäufen über diese Website:<br>Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, Deutschland, E-Mail: goldmoodastro@gmail.com.<br>Für den Plattformbetrieb (Konten, Inhalte, Terminverwaltung) ist der Plattformbetreiber QUEBAB GIDA ... TİCARET LİMİTED ŞİRKETİ (Istanbul, Türkei) verantwortlich; Einzelheiten enthält die türkische Datenschutz-/KVKK-Erklärung.</p><h3>2. Verarbeitete Daten und Zwecke</h3><ul><li><strong>Konto- und Profildaten</strong> (Name, E-Mail, ggf. Geburtsdaten für astrologische Berechnungen) — Vertragserfüllung, Art. 6 Abs. 1 lit. b DSGVO.</li><li><strong>Termin- und Sitzungsdaten</strong> (Berater, Datum, Dauer, Sitzungsform) — Vertragserfüllung.</li><li><strong>Zahlungsdaten</strong> — Verarbeitung durch Zahlungsdienstleister (siehe Ziff. 3); Kartendaten werden von uns nicht gespeichert.</li><li><strong>Server-Logs und Cookies</strong> — berechtigtes Interesse an Sicherheit und Stabilität, Art. 6 Abs. 1 lit. f DSGVO; Einzelheiten in der Cookie-Richtlinie.</li></ul><h3>3. Zahlungsdienstleister</h3><p><strong>Stripe:</strong> Zahlungen per Kredit-/Debitkarte werden über Stripe Payments Europe, Ltd. (Irland) abgewickelt. Stripe verarbeitet Zahlungsdaten als eigener Verantwortlicher bzw. Auftragsverarbeiter; Informationen: <a href=\\"https://stripe.com/de/privacy\\" rel=\\"noopener\\">stripe.com/de/privacy</a>.</p><p><strong>PayPal:</strong> Bei Zahlung über PayPal gelten die Datenschutzhinweise der PayPal (Europe) S.à r.l. et Cie, S.C.A.: <a href=\\"https://www.paypal.com/de/webapps/mpp/ua/privacy-full\\" rel=\\"noopener\\">paypal.com</a>.</p><h3>4. Empfänger und Drittlandübermittlung</h3><p>Hosting- und Infrastruktur-Dienstleister, Zahlungsdienstleister sowie der Plattformbetreiber in der Türkei. Übermittlungen in Drittländer erfolgen auf Grundlage von Standardvertragsklauseln oder Ihrer Einwilligung.</p><h3>5. Speicherdauer</h3><p>Daten werden gelöscht, sobald sie für die genannten Zwecke nicht mehr erforderlich sind und keine gesetzlichen Aufbewahrungspflichten (z. B. steuerrechtlich: 8–10 Jahre) entgegenstehen. Kontolöschung kann im Konto beantragt werden.</p><h3>6. Ihre Rechte</h3><p>Sie haben das Recht auf Auskunft, Berichtigung, Löschung, Einschränkung, Datenübertragbarkeit und Widerspruch (Art. 15–21 DSGVO) sowie das Recht auf Beschwerde bei einer Aufsichtsbehörde; zuständig für den Verantwortlichen ist die Landesbeauftragte für Datenschutz und Informationsfreiheit Nordrhein-Westfalen.</p><h3>7. Keine automatisierte Entscheidungsfindung</h3><p>Eine ausschließlich automatisierte Entscheidungsfindung mit Rechtswirkung findet nicht statt. KI-gestützte Inhalte (z. B. Tageshoroskope) dienen nur der Information und Unterhaltung.</p>"}', 'DSGVO-Datenschutzerklärung inkl. Stripe/PayPal.', 'Datenschutzerklärung — Gold Mood Astro', 'DSGVO-konforme Datenschutzerklärung von Gold Mood Astro.'),
  ('cpi-datenschutz-tr', 'cp-datenschutz', 'tr', 'Veri Koruma Beyanı (DSGVO)', 'veri-koruma-beyani-dsgvo', '{"html": "<h2>Veri Koruma Beyanı (DSGVO / GDPR)</h2><p>Bu beyan, kart ödemeleri ve dijital satışlar kapsamında Avrupa Birliği Genel Veri Koruma Tüzüğü (DSGVO/GDPR) uyarınca yapılan veri işlemeyi açıklar. Platformun genel KVKK aydınlatma metni ayrıca yürürlüktedir.</p><h3>1. Veri sorumlusu</h3><p>Kart ödemeleri ve dijital satışlar için: Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, Almanya, e-posta: goldmoodastro@gmail.com. Platform işletimi (hesaplar, içerik, randevular) için QUEBAB ... LTD ŞTİ (İstanbul) sorumludur.</p><h3>2. İşlenen veriler ve amaçlar</h3><ul><li>Hesap ve profil verileri (ad, e-posta, astrolojik hesaplama için doğum bilgileri) — sözleşmenin ifası.</li><li>Randevu ve seans verileri — sözleşmenin ifası.</li><li>Ödeme verileri — ödeme kuruluşlarınca işlenir; kart bilgileri sistemlerimizde saklanmaz.</li><li>Sunucu kayıtları ve çerezler — güvenlik ve kararlılık; ayrıntılar Çerez Politikasında.</li></ul><h3>3. Ödeme kuruluşları</h3><p>Stripe (Stripe Payments Europe, Ltd.) ve PayPal (PayPal Europe S.à r.l.) kendi gizlilik politikaları kapsamında ödeme verilerini işler.</p><h3>4. Haklarınız</h3><p>DSGVO m. 15–21 kapsamında bilgi, düzeltme, silme, kısıtlama, taşınabilirlik ve itiraz haklarına; ayrıca denetim makamına şikâyet hakkına sahipsiniz.</p>"}', 'Kart ödemeleri için DSGVO veri koruma beyanı.', 'Veri Koruma Beyanı (DSGVO) — Gold Mood Astro', 'Gold Mood Astro DSGVO veri koruma beyanı.'),
  ('cpi-datenschutz-en', 'cp-datenschutz', 'en', 'Privacy Policy (GDPR)', 'privacy-policy-gdpr', '{"html": "<h2>Privacy Policy (GDPR)</h2><p>This notice explains processing under the EU GDPR in connection with card payments and digital sales. The platform’s general privacy/KVKK notice also applies.</p><h3>1. Controller</h3><p>For card payments and digital sales: Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, Germany, email: goldmoodastro@gmail.com. For platform operation (accounts, content, appointments): QUEBAB ... LTD ŞTİ (Istanbul, Türkiye).</p><h3>2. Data and purposes</h3><ul><li>Account and profile data (name, email, birth data for astrological calculations) — performance of contract.</li><li>Appointment and session data — performance of contract.</li><li>Payment data — processed by payment providers; we do not store card details.</li><li>Server logs and cookies — security and stability; see the Cookie Policy.</li></ul><h3>3. Payment providers</h3><p>Stripe (Stripe Payments Europe, Ltd.) and PayPal (PayPal Europe S.à r.l.) process payment data under their own privacy policies.</p><h3>4. Your rights</h3><p>You have the rights of access, rectification, erasure, restriction, portability and objection (Art. 15–21 GDPR) and the right to lodge a complaint with a supervisory authority.</p>"}', 'GDPR privacy notice incl. Stripe/PayPal.', 'Privacy Policy (GDPR) — Gold Mood Astro', 'GDPR privacy policy of Gold Mood Astro.')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), slug = VALUES(slug), content = VALUES(content),
  summary = VALUES(summary), meta_title = VALUES(meta_title), meta_description = VALUES(meta_description);

INSERT INTO custom_pages_i18n (id, custom_page_id, locale, title, slug, content, summary, meta_title, meta_description) VALUES
  ('cpi-agb-de', 'cp-agb', 'de', 'Allgemeine Geschäftsbedingungen (AGB)', 'agb', '{"html": "<h2>Allgemeine Geschäftsbedingungen (AGB)</h2><h3>1. Geltungsbereich und Vertragspartner</h3><p>Diese AGB gelten für alle über goldmoodastro.com per Kredit-/Debitkarte oder PayPal abgeschlossenen Käufe von Beratungsleistungen und digitalen Inhalten. Vertragspartner ist Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, Deutschland (USt-IdNr. DE463832419). Der Plattformbetrieb erfolgt unter der Marke Gold Mood Astro.</p><h3>2. Leistungen</h3><p>Angeboten werden astrologie-basierte persönliche Beratungen (Audio-/Video-Termine, Nachrichtenberatung) und digitale Inhalte (z. B. schriftliche Deutungen, Tarot-Lesungen, Geburtshoroskop-Auswertungen). Alle Leistungen dienen ausschließlich der persönlichen Achtsamkeit, Reflexion und Unterhaltung. Es werden keine medizinischen Diagnosen, Behandlungs-, Rechts- oder Anlageberatungen erbracht und keine Ergebnisse garantiert.</p><h3>3. Vertragsschluss</h3><p>Die Darstellung der Leistungen ist kein bindendes Angebot. Mit Abschluss des Bezahlvorgangs gibt der Kunde ein Angebot ab; der Vertrag kommt mit der Buchungs-/Zahlungsbestätigung per E-Mail zustande.</p><h3>4. Preise und Zahlung</h3><p>Alle Preise sind Endpreise. Gemäß § 19 UStG wird keine Umsatzsteuer ausgewiesen. Die Zahlung erfolgt über Stripe (Karte, 3-D Secure) oder PayPal. Die Abrechnung erfolgt in Euro; bei Anzeige in anderer Währung ist der Euro-Betrag maßgeblich.</p><h3>5. Termine, Stornierung</h3><p>Bis 24 Stunden vor dem Termin kann kostenlos storniert werden. Danach sowie nach Sitzungsbeginn besteht kein Erstattungsanspruch; Einzelheiten regelt die Stornierungs- und Erstattungsrichtlinie. Erscheint der Berater nicht, erhält der Kunde volle Erstattung oder einen kostenlosen Ersatztermin.</p><h3>6. Widerrufsrecht</h3><p>Verbrauchern steht das gesetzliche Widerrufsrecht nach Maßgabe der Widerrufsbelehrung zu. Bei digitalen Inhalten erlischt es unter den Voraussetzungen des § 356 Abs. 5 BGB, bei Dienstleistungen nach § 356 Abs. 4 BGB.</p><h3>7. Mindestalter</h3><p>Das Angebot richtet sich ausschließlich an Personen ab 18 Jahren.</p><h3>8. Haftung</h3><p>Für Entscheidungen, die der Kunde auf Grundlage von Beratungsinhalten trifft, wird keine Haftung übernommen. Im Übrigen haften wir unbeschränkt bei Vorsatz und grober Fahrlässigkeit sowie nach dem Produkthaftungsgesetz; bei einfacher Fahrlässigkeit nur für die Verletzung wesentlicher Vertragspflichten, begrenzt auf den vorhersehbaren, vertragstypischen Schaden.</p><h3>9. Schlussbestimmungen</h3><p>Es gilt deutsches Recht unter Ausschluss des UN-Kaufrechts; gegenüber Verbrauchern bleiben zwingende Verbraucherschutzvorschriften ihres Aufenthaltsstaats unberührt.</p>"}', 'AGB für Kartenkäufe und digitale Inhalte.', 'AGB — Gold Mood Astro', 'Allgemeine Geschäftsbedingungen von Gold Mood Astro.'),
  ('cpi-agb-tr', 'cp-agb', 'tr', 'Genel İşlem Koşulları (AGB)', 'genel-islem-kosullari-agb', '{"html": "<h2>Genel İşlem Koşulları (AGB)</h2><h3>1. Kapsam ve sözleşme tarafı</h3><p>Bu koşullar, goldmoodastro.com üzerinden kredi/banka kartı veya PayPal ile satın alınan danışmanlık hizmetleri ve dijital içerikler için geçerlidir. Sözleşme tarafı: Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, Almanya (KDV No: DE463832419). Platform, Gold Mood Astro markası altında işletilir.</p><h3>2. Hizmetler</h3><p>Astroloji temelli kişisel danışmanlık (sesli/görüntülü randevu, mesajla danışma) ve dijital içerikler (yazılı yorum, tarot okuması, doğum haritası değerlendirmesi) sunulur. Tüm hizmetler yalnızca kişisel farkındalık ve eğlence amaçlıdır; tıbbi, hukuki, finansal danışmanlık verilmez, sonuç garanti edilmez.</p><h3>3. Sözleşmenin kurulması</h3><p>Ödeme adımının tamamlanmasıyla kullanıcı teklifte bulunur; sözleşme, e-posta ile gönderilen rezervasyon/ödeme onayıyla kurulur.</p><h3>4. Fiyatlar ve ödeme</h3><p>Fiyatlar nihai fiyattır; § 19 UStG uyarınca KDV gösterilmez. Ödeme Stripe (kart, 3-D Secure) veya PayPal ile alınır; tahsilat Euro cinsindendir.</p><h3>5. Randevu ve iptal</h3><p>Randevuya 24 saatten fazla süre varken ücretsiz iptal edilebilir. Sonrasında ve seans başladıktan sonra iade yapılmaz; ayrıntılar İptal ve İade Politikasındadır. Danışman katılmazsa tam iade veya ücretsiz yeni randevu sunulur.</p><h3>6. Cayma hakkı</h3><p>Tüketiciler için yasal cayma hakkı, Cayma Bilgilendirmesi (Widerrufsbelehrung) sayfasında açıklanan koşullarla geçerlidir.</p><h3>7. Yaş sınırı</h3><p>Hizmetler yalnızca 18 yaşını doldurmuş kişilere yöneliktir.</p><h3>8. Sorumluluk</h3><p>Danışmanlık içeriğine dayanarak alınan kararlardan sorumluluk kabul edilmez. Kasıt ve ağır kusurda sınırsız; basit kusurda yalnızca esaslı sözleşme yükümlülükleri için ve öngörülebilir zararla sınırlı sorumluluk geçerlidir.</p><h3>9. Uygulanacak hukuk</h3><p>Alman hukuku uygulanır; tüketicinin mutad meskeni ülkesindeki emredici koruma hükümleri saklıdır.</p>"}', 'Kart satış kanalı için genel işlem koşulları.', 'Genel İşlem Koşulları — Gold Mood Astro', 'Gold Mood Astro genel işlem koşulları (AGB).'),
  ('cpi-agb-en', 'cp-agb', 'en', 'Terms and Conditions (AGB)', 'terms-and-conditions', '{"html": "<h2>Terms and Conditions</h2><h3>1. Scope and contracting party</h3><p>These terms apply to purchases of consulting services and digital content via goldmoodastro.com paid by credit/debit card or PayPal. Contracting party: Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, Germany (VAT ID DE463832419). The platform operates under the Gold Mood Astro brand.</p><h3>2. Services</h3><p>Astrology-based personal consulting (audio/video appointments, messaging) and digital content (written readings, tarot readings, birth-chart analyses). All services serve personal awareness, reflection and entertainment only; no medical, legal or investment advice, no guaranteed outcomes.</p><h3>3. Conclusion of contract</h3><p>Completing checkout constitutes an offer by the customer; the contract is concluded upon the booking/payment confirmation email.</p><h3>4. Prices and payment</h3><p>Prices are final; no VAT is shown pursuant to § 19 UStG. Payment via Stripe (card, 3-D Secure) or PayPal; settlement in euros.</p><h3>5. Appointments and cancellation</h3><p>Free cancellation up to 24 hours before the appointment. Afterwards and once the session starts, no refund; details in the Cancellation and Refund Policy. If the consultant does not attend: full refund or free replacement appointment.</p><h3>6. Right of withdrawal</h3><p>Consumers have the statutory right of withdrawal as described in the Withdrawal Notice.</p><h3>7. Minimum age</h3><p>Services are offered to persons aged 18 or over only.</p><h3>8. Liability</h3><p>No liability for decisions taken based on consulting content. Otherwise unlimited liability for intent and gross negligence; for slight negligence only for breach of essential obligations, limited to foreseeable typical damage.</p><h3>9. Governing law</h3><p>German law applies; mandatory consumer protections of the consumer’s state of residence remain unaffected.</p>"}', 'Terms for card purchases and digital content.', 'Terms and Conditions — Gold Mood Astro', 'Terms and conditions of Gold Mood Astro.')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), slug = VALUES(slug), content = VALUES(content),
  summary = VALUES(summary), meta_title = VALUES(meta_title), meta_description = VALUES(meta_description);

INSERT INTO custom_pages_i18n (id, custom_page_id, locale, title, slug, content, summary, meta_title, meta_description) VALUES
  ('cpi-widerruf-de', 'cp-widerruf', 'de', 'Widerrufsbelehrung', 'widerrufsbelehrung', '{"html": "<h2>Widerrufsbelehrung</h2><h3>Widerrufsrecht</h3><p>Verbraucher haben das Recht, binnen vierzehn Tagen ohne Angabe von Gründen diesen Vertrag zu widerrufen. Die Widerrufsfrist beträgt vierzehn Tage ab dem Tag des Vertragsschlusses.</p><p>Um Ihr Widerrufsrecht auszuüben, müssen Sie uns (Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, Deutschland, E-Mail: goldmoodastro@gmail.com) mittels einer eindeutigen Erklärung (z. B. E-Mail) über Ihren Entschluss informieren. Sie können dafür das untenstehende Muster-Widerrufsformular verwenden.</p><h3>Folgen des Widerrufs</h3><p>Im Falle eines wirksamen Widerrufs erstatten wir alle erhaltenen Zahlungen unverzüglich, spätestens binnen vierzehn Tagen ab Zugang der Widerrufserklärung, über dasselbe Zahlungsmittel.</p><h3>Vorzeitiges Erlöschen des Widerrufsrechts</h3><p><strong>Dienstleistungen (Beratungstermine):</strong> Das Widerrufsrecht erlischt, wenn wir die Leistung vollständig erbracht haben und mit der Ausführung erst begonnen haben, nachdem Sie Ihre ausdrückliche Zustimmung gegeben und Ihre Kenntnis vom Verlust des Widerrufsrechts bestätigt haben (§ 356 Abs. 4 BGB). Haben Sie den Beginn vor Fristablauf verlangt, schulden Sie bei Widerruf Wertersatz für die bereits erbrachte Teilleistung.</p><p><strong>Digitale Inhalte (z. B. sofort bereitgestellte schriftliche Deutungen):</strong> Das Widerrufsrecht erlischt, wenn wir mit der Ausführung begonnen haben, nachdem Sie ausdrücklich zugestimmt und bestätigt haben, dass Sie mit Beginn der Ausführung Ihr Widerrufsrecht verlieren (§ 356 Abs. 5 BGB).</p><h3>Muster-Widerrufsformular</h3><p><em>(Wenn Sie den Vertrag widerrufen wollen, füllen Sie bitte dieses Formular aus und senden Sie es zurück.)</em></p><p>An: Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, E-Mail: goldmoodastro@gmail.com<br>— Hiermit widerrufe(n) ich/wir den von mir/uns abgeschlossenen Vertrag über die Erbringung der folgenden Dienstleistung: …<br>— Bestellt am: … / Buchungsnummer: …<br>— Name und Anschrift des/der Verbraucher(s): …<br>— Datum, Unterschrift (nur bei Mitteilung auf Papier)</p>"}', 'Gesetzliche Widerrufsbelehrung mit Musterformular.', 'Widerrufsbelehrung — Gold Mood Astro', 'Widerrufsbelehrung und Muster-Widerrufsformular von Gold Mood Astro.'),
  ('cpi-widerruf-tr', 'cp-widerruf', 'tr', 'Cayma Hakkı Bilgilendirmesi (AB)', 'cayma-hakki-bilgilendirmesi-ab', '{"html": "<h2>Cayma Hakkı Bilgilendirmesi (AB Tüketicileri)</h2><h3>Cayma hakkı</h3><p>Tüketiciler, sözleşmenin kurulduğu günden itibaren on dört gün içinde gerekçe göstermeksizin cayma hakkına sahiptir. Cayma bildirimi açık bir beyanla (ör. e-posta) şu adrese yapılır: Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, Almanya, e-posta: goldmoodastro@gmail.com.</p><h3>Caymanın sonuçları</h3><p>Geçerli caymada alınan ödemeler, bildirimin ulaşmasından itibaren en geç on dört gün içinde aynı ödeme aracıyla iade edilir.</p><h3>Cayma hakkının erken sona ermesi</h3><p><strong>Danışmanlık randevuları:</strong> Açık onayınızla ve cayma hakkını kaybedeceğinizi bildiğinizi teyit etmenizle hizmete başlanmış ve hizmet tamamen ifa edilmişse cayma hakkı sona erer (§ 356/4 BGB). Süre dolmadan başlamayı talep ettiyseniz, caymada ifa edilen kısım için bedel ödenir.</p><p><strong>Dijital içerikler:</strong> Açık onayınız ve hak kaybı teyidinizle içerik sunulmaya başlandığında cayma hakkı sona erer (§ 356/5 BGB).</p><h3>Örnek cayma formu</h3><p>Alıcı: Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich — İşbu beyanla aşağıdaki hizmete ilişkin sözleşmeden caydığımı bildiririm: … / Sipariş tarihi ve rezervasyon numarası: … / Ad, adres: … / Tarih, imza (yalnız kâğıt bildirimde)</p>"}', 'AB tüketicileri için yasal cayma bilgilendirmesi.', 'Cayma Hakkı Bilgilendirmesi — Gold Mood Astro', 'Gold Mood Astro AB cayma hakkı bilgilendirmesi ve örnek form.'),
  ('cpi-widerruf-en', 'cp-widerruf', 'en', 'Withdrawal Notice (EU)', 'withdrawal-notice', '{"html": "<h2>Withdrawal Notice (EU Consumers)</h2><h3>Right of withdrawal</h3><p>Consumers may withdraw from this contract within fourteen days without giving reasons, starting on the day the contract is concluded. To exercise the right, inform us by an unequivocal statement (e.g. email): Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, Germany, email: goldmoodastro@gmail.com.</p><h3>Effects of withdrawal</h3><p>In case of an effective withdrawal we refund all payments received without undue delay and no later than fourteen days from receipt of the notice, using the same means of payment.</p><h3>Early expiry of the right</h3><p><strong>Services (consulting appointments):</strong> The right expires once the service has been fully performed, where performance began with your express consent and your acknowledgement that you lose the right upon full performance (§ 356(4) BGB). If you requested performance before expiry of the period, you owe compensation for the part already performed.</p><p><strong>Digital content:</strong> The right expires once performance has begun with your express consent and acknowledgement of the loss of the right (§ 356(5) BGB).</p><h3>Model withdrawal form</h3><p>To: Orhan Güzel – Softwareentwicklung, Stralsunder Str. 38, 41515 Grevenbroich, email: goldmoodastro@gmail.com — I/we hereby withdraw from the contract for the following service: … / Ordered on / booking number: … / Name and address: … / Date, signature (only for paper notice)</p>"}', 'Statutory EU withdrawal notice with model form.', 'Withdrawal Notice — Gold Mood Astro', 'EU withdrawal notice and model form of Gold Mood Astro.')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), slug = VALUES(slug), content = VALUES(content),
